1	/*
2	 * Rounding — a single rule with two faces.
3	 *
4	 * Money is only ever settled in whole gold pieces, and a fraction of a gold
5	 * piece always falls to MHPCO. Which way that rounds depends on who is paying:
6	 * a premium the customer owes rounds up, a payout MHPCO owes rounds down.
7	 * Both functions below are that one rule; keep them together so a change of
8	 * heart about it is a change in one place.
9	 */
10	
11	/** Premiums are rounded up — the fraction falls to MHPCO. */
12	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
13	
14	/** Payouts are rounded down — the fraction stays with MHPCO. */
15	const roundPayoutDown = (amount: number): number => Math.floor(amount);
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type QuoteStep = { op: string; items: Item[] };
25	
26	export type Damage = { itemType: string; amount: number };
27	
28	export type Incident = { cause: string; damages: Damage[] };
29	
30	export type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	export type Step = QuoteStep | ClaimStep;
33	
34	export type Item = { type: string } & Record<string, unknown>;
35	
36	export type QuoteResult = { premium: number };
37	
38	export type ClaimResult = { payout: number; remainingCap: number };
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export type ScenarioOutcome = { results: Result[] };
43	
44	// ---------------------------------------------------------------------------
45	// Quoting — what a policy costs the customer.
46	// ---------------------------------------------------------------------------
47	
48	/** Base premium of each insurable item type. */
49	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
50	  sword: 100,
51	  amulet: 60,
52	  staff: 80,
53	  potion: 40,
54	  rune: 25,
55	  moonstone: 25,
56	};
57	
58	/** A block is exactly this many items of one and the same type. */
59	const BLOCK_SIZE = 3;
60	
61	/** Special base premium charged for a complete block, instead of the per-item sum. */
62	const BLOCK_BASE_PREMIUM = 60;
63	
64	/** Number of items of each type on a policy. */
65	const countByType = (items: Item[]): Map<string, number> => {
66	  const counts = new Map<string, number>();
67	  for (const item of items) {
68	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
69	  }
70	  return counts;
71	};
72	
73	/**
74	 * Base premium of a single item of the given type, before block pricing or
75	 * surcharge. A type MHPCO does not insure has no base premium, so this throws
76	 * rather than inventing one — an unpriceable item must not silently become a
77	 * NaN premium.
78	 *
79	 * This is also the only place a quote checks that a type is insurable at all.
80	 * Every item reaches it via the surcharge pass, which prices items one by one;
81	 * the block path in `groupBasePremium` skips the lookup, so it alone would let
82	 * a complete block of an unknown type through.
83	 */
84	const basePremiumOfType = (type: string): number => {
85	  const basePremium = BASE_PREMIUM_BY_TYPE[type];
86	  if (basePremium === undefined) {
87	    throw new Error(`Unknown item type: ${type}`);
88	  }
89	  return basePremium;
90	};
91	
92	/** Base premium for all items of one and the same type. */
93	const groupBasePremium = (type: string, count: number): number =>
94	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
95	
96	/** Base premium of a policy covering the given items. */
97	const calculateBasePremium = (items: Item[]): number =>
98	  [...countByType(items)].reduce(
99	    (total, [type, count]) => total + groupBasePremium(type, count),
100	    0,
101	  );
102	
103	/** Risk surcharge charged on the base premium of a cursed item. */
104	const CURSE_RATE = 0.5;
105	
106	/** Enchantment level from which an item counts as highly enchanted. */
107	const HIGH_ENCHANTMENT_LEVEL = 5;
108	
109	/** Risk surcharge charged on the base premium of a highly enchanted item. */
110	const HIGH_ENCHANTMENT_RATE = 0.3;
111	
112	/** True when the item is enchanted strongly enough to attract the surcharge. */
113	const isHighlyEnchanted = (item: Item): boolean =>
114	  typeof item.enchantment === "number" &&
115	  item.enchantment >= HIGH_ENCHANTMENT_LEVEL;
116	
117	/** Combined rate of the surcharges an item attracts. */
118	const itemSurchargeRate = (item: Item): number => {
119	  const curseRate = item.cursed ? CURSE_RATE : 0;
120	  const enchantmentRate = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RATE : 0;
121	  return curseRate + enchantmentRate;
122	};
123	
124	/** Surcharges an individual item attracts, charged on its own base premium. */
125	const itemSurcharges = (item: Item): number =>
126	  basePremiumOfType(item.type) * itemSurchargeRate(item);
127	
128	/** Surcharges that attach to individual items rather than to the whole policy. */
129	const calculateItemSurcharges = (items: Item[]): number =>
130	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
131	
132	/** Initial assessment surcharge on a customer's first insurance. */
133	const FIRST_INSURANCE_RATE = 0.1;
134	
135	/** Years of business from which a customer counts as long-standing. */
136	const LOYALTY_YEARS = 2;
137	
138	/** Discount a long-standing customer receives on the policy base premium. */
139	const LOYALTY_RATE = -0.2;
140	
141	/** True when the customer has been with MHPCO long enough to earn the discount. */
142	const isLongStanding = (customer: Customer): boolean =>
143	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
144	
145	/** Discount on every contract after the customer's first. */
146	const FOLLOW_UP_RATE = -0.15;
147	
148	/** True when this is not the customer's first contract. */
149	const isFollowUpContract = (
150	  _customer: Customer,
151	  previousContracts: number,
152	): boolean => previousContracts > 0;
153	
154	/**
155	 * Rates that attach to the policy as a whole. Each applies to the policy base
156	 * premium; positive rates are surcharges, negative ones discounts.
157	 */
158	const POLICY_RATES: {
159	  rate: number;
160	  applies: (customer: Customer, previousContracts: number) => boolean;
161	}[] = [
162	  { rate: FIRST_INSURANCE_RATE, applies: () => true },
163	  { rate: LOYALTY_RATE, applies: isLongStanding },
164	  { rate: FOLLOW_UP_RATE, applies: isFollowUpContract },
165	];
166	
167	/** Net of every policy-wide rate the customer qualifies for. */
168	const policyRate = (customer: Customer, previousContracts: number): number =>
169	  POLICY_RATES.reduce(
170	    (total, { rate, applies }) =>
171	      applies(customer, previousContracts) ? total + rate : total,
172	    0,
173	  );
174	
175	/** Net policy-wide adjustment, charged on the policy base premium. */
176	const calculatePolicyAdjustment = (
177	  policyBasePremium: number,
178	  customer: Customer,
179	  previousContracts: number,
180	): number => policyBasePremium * policyRate(customer, previousContracts);
181	
182	/** Flat fee added to every premium, regardless of the items insured. */
183	const PROCESSING_FEE = 5;
184	
185	/** Price a policy covering the given items. */
186	const quotePremium = (
187	  items: Item[],
188	  customer: Customer,
189	  previousContracts: number,
190	): number => {
191	  const policyBasePremium = calculateBasePremium(items);
192	  const surcharges = calculateItemSurcharges(items);
193	  const policyAdjustment = calculatePolicyAdjustment(
194	    policyBasePremium,
195	    customer,
196	    previousContracts,
197	  );
198	  return roundPremiumUp(
199	    policyBasePremium + surcharges + policyAdjustment + PROCESSING_FEE,
200	  );
201	};
202	
203	// ---------------------------------------------------------------------------
204	// Claims — what a policy pays out when insured items are damaged.
205	// ---------------------------------------------------------------------------
206	
207	/** Sum insured for each item type, per the MHPCO price list. */
208	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
209	  sword: 1000,
210	  amulet: 600,
211	  staff: 800,
212	  potion: 400,
213	  rune: 250,
214	  moonstone: 250,
215	};
216	
217	/** Excess the claimant bears on every damaged item. */
218	const DEDUCTIBLE = 100;
219	
220	/** A policy pays out at most this multiple of its insurance sum. */
221	const CAP_MULTIPLIER = 2;
222	
223	/** Total sum insured under a policy covering the given items. */
224	const insuranceSum = (items: Item[]): number =>
225	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
226	
227	/** Enchantment level from which damage is only partly reimbursed. */
228	const REDUCED_REIMBURSEMENT_LEVEL = 8;
229	
230	/** Share of the damage MHPCO reimburses on a heavily enchanted item. */
231	const REDUCED_REIMBURSEMENT_RATE = 0.5;
232	
233	/** Share of the damage MHPCO reimburses for the given insured item. */
234	const reimbursementRate = (item: Item): number =>
235	  typeof item.enchantment === "number" &&
236	  item.enchantment >= REDUCED_REIMBURSEMENT_LEVEL
237	    ? REDUCED_REIMBURSEMENT_RATE
238	    : 1;
239	
240	/** What MHPCO owes for a single damaged item, before the cap is considered. */
241	const damagePayout = (damage: Damage, item: Item): number =>
242	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
243	
244	/** A quoted policy, tracked so later claim steps can draw against its cap. */
245	type Policy = { items: Item[]; remainingCap: number };
246	
247	/** The policy a quote step establishes, with its cap untouched. */
248	const openPolicy = (items: Item[]): Policy => ({
249	  items,
250	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
251	});
252	
253	/** The insured item a damage entry refers to. */
254	const damagedItem = (policy: Policy, damage: Damage): Item => {
255	  const item = policy.items.find((item) => item.type === damage.itemType);
256	  if (item === undefined) {
257	    throw new Error(
258	      `Damaged item not covered by the policy: ${damage.itemType}`,
259	    );
260	  }
261	  return item;
262	};
263	
264	/** What MHPCO owes for an entire incident, before the cap is considered. */
265	const grossIncidentPayout = (incident: Incident, policy: Policy): number =>
266	  incident.damages.reduce(
267	    (total, damage) => total + damagePayout(damage, damagedItem(policy, damage)),
268	    0,
269	  );
270	
271	/**
272	 * Draws an amount owed against the policy's cap. A policy never pays out more
273	 * than the cap it has left, so the amount drawn is whichever is smaller.
274	 */
275	const drawAgainstCap = (policy: Policy, amountOwed: number): number => {
276	  const drawn = Math.min(roundPayoutDown(amountOwed), policy.remainingCap);
277	  policy.remainingCap -= drawn;
278	  return drawn;
279	};
280	
281	// ---------------------------------------------------------------------------
282	// Running a scenario — quote steps open policies, claim steps draw on them.
283	// ---------------------------------------------------------------------------
284	
285	/** True when the step reports damage against a policy rather than asking for a price. */
286	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
287	
288	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
289	  const policies = new Map<number, Policy>();
290	  let previousContracts = 0;
291	
292	  const handleQuote = (step: QuoteStep, stepIndex: number): QuoteResult => {
293	    const premium = quotePremium(
294	      step.items,
295	      scenario.customer,
296	      previousContracts,
297	    );
298	    previousContracts += 1;
299	    policies.set(stepIndex, openPolicy(step.items));
300	    return { premium };
301	  };
302	
303	  const handleClaim = (step: ClaimStep): ClaimResult => {
304	    const policy = policies.get(step.policy)!;
305	    const payout = drawAgainstCap(
306	      policy,
307	      grossIncidentPayout(step.incident, policy),
308	    );
309	    return { payout, remainingCap: policy.remainingCap };
310	  };
311	
312	  const results = scenario.steps.map((step, stepIndex): Result =>
313	    isClaimStep(step) ? handleClaim(step) : handleQuote(step, stepIndex),
314	  );
315	
316	  return { results };
317	};
